  add("El ascenso a División de Honor — Lô Esport Menorca", "L'ascens a Divisió d'Honor — Lô Esport Menorca", "O ascenso a División de Honra — Lô Esport Menorca", "Ohorezko Mailarako igoera — Lô Esport Menorca");
  add("El ascenso de Lô Esport Menorca a División de Honor en 2026, contado con el pulso de aquel domingo en Pamplona y el orgullo de una isla entera.", "L'ascens de Lô Esport Menorca a Divisió d'Honor el 2026, explicat amb el pols d'aquell diumenge a Pamplona i l'orgull d'una illa sencera.", "O ascenso de Lô Esport Menorca a División de Honra en 2026, contado co pulso daquel domingo en Pamplona e co orgullo dunha illa enteira.", "Lô Esport Menorcak 2026an Ohorezko Mailara egindako igoera, Iruñeko igande haren taupadarekin eta uharte oso baten harrotasunarekin kontatua.");
  add("Ascenso histórico", "Ascens històric", "Ascenso histórico", "Igoera historikoa");
